owner_prospect.validation:
requestSchema = z.object({
  listingId: z.string().min(1).max(200),
  action: z.enum(['add', 'remove', 'retry']),
})

property_remove.validation:
removalSchema = z.object({
  propertyId: z.string().regex(/^[A-Za-z0-9_-]{1,150}$/),
  reason: z.enum(['not_interesting', 'collaboration_ended', 'sold']),
  soldDisposition: z.enum(['agency', 'other_agency', 'owner']).optional(),
  soldPrice: z.number().finite().positive().max(1e12).optional(),
  agentMessage: z.string().trim().max(4000),
}).strict().superRefine((value, ctx) => {
  if (value.reason === 'sold' && (!value.soldDisposition || !value.soldPrice)) {
    ctx.addIssue({ code: z.ZodIssueCode.custom, message: 'Completează prețul și autorul vânzării.' });
  }
})

sale_setup.validation:
participantSchema = z.object({
  id: z.string().min(1).max(200),
  role: z.enum(['buyer', 'owner', 'notary', 'collaborator']),
  contactId: z.string().nullable().optional(),
  name: z.string().trim().max(200),
  email: z.string().trim().email().or(z.literal('')),
  phone: z.string().trim().max(50).nullable().optional(),
  preferredChannel: z.enum(['email', 'phone', 'whatsapp']).optional(),
})

checklistSchema = z.object({
  id: z.string().min(1).max(200),
  label: z.string().trim().min(1).max(240),
  participantRole: z.enum(['buyer', 'owner']),
  stage: z.enum(['reservation', 'precontract', 'contract']).optional(),
  status: z.enum(['required', 'requested', 'received_needs_review', 'verified', 'rejected', 'expired', 'not_required']),
  required: z.boolean(),
}).passthrough()

setupSchema = z.object({
  participants: z.array(participantSchema).min(2).max(20),
  agreedPrice: z.number().positive().max(1_000_000_000).nullable(),
  reservationAmount: z.number().nonnegative().max(1_000_000_000).nullable().optional().default(null),
  precontractAmount: z.number().nonnegative().max(1_000_000_000).nullable().optional().default(null),
  financingType: z.enum(['cash', 'credit', 'unknown']),
  checklist: z.array(checklistSchema).max(100),
  notary: z.object({
    name: z.string().trim().max(200).nullable().optional(),
    email: z.string().trim().email().or(z.literal('')).nullable().optional(),
    phone: z.string().trim().max(50).nullable().optional(),
    address: z.string().trim().max(400).nullable().optional(),
    appointmentAt: z.string().datetime().nullable().optional(),
  }).nullable(),
}).superRefine((value, context) => {
  if (value.agreedPrice != null && (value.reservationAmount ?? 0) + (value.precontractAmount ?? 0) > value.agreedPrice) {
    context.addIssue({ code: 'custom', path: ['precontractAmount'], message: 'Rezervarea și antecontractul nu pot depăși prețul de vânzare.' });
  }
})

outreach_calls.validation:
callSchema = z.object({
  ownerListing: z.object({
    id: z.string().min(1),
    title: z.string().min(1),
    price: z.string().optional(),
    location: z.string().optional(),
    link: z.string().optional(),
    ownerPhone: z.string().optional(),
    description: z.string().optional(),
  }),
  scheduledAt: z.string().nullable().optional(),
})

contract_generate.validation:
requestSchema = z.object({
  values: z.record(z.union([z.string(), z.number(), z.boolean(), z.null()])),
  contactId: z.string().nullable().optional(),
  ownerId: z.string().nullable().optional(),
  propertyId: z.string().nullable().optional(),
})

agency_agents.validation:
createAgentSchema = z.object({
  name: z.string().trim().min(2, 'Numele agentului este obligatoriu.'),
  email: z.string().email('Adresa de email este invalida.'),
  phone: z.string().trim().optional(),
  password: z.string().trim().optional(),
})

agency_agent_detail.validation:
updateAgentSchema = z.object({
  name: z.string().trim().min(2, 'Numele agentului este obligatoriu.'),
  phone: z.string().trim().optional(),
  photoUrl: z.string().url('URL-ul pozei este invalid.').or(z.literal('')).optional(),
})
